// Coordinated switches on the 34 nonroot vertices: core 0..25, eight newcomers 26..33. Keep the root implicit, degree 8 in full endpoint and no red triangles. Score actual simultaneous region failures on ONE coloring. Save best by (small-region failures, five-, six-, seven-, eight-label failures). Not an exclusion search.
use std::io::{self,Read};type G=[u64;34];fn has(g:&G,mut p:u64,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros()as usize;p&=p-1;if has(g,p&!g[i],k-1){return true}}false}fn profile(g:&G)->[i32;5]{let mut a=[0;5];let mut p=[0u64;256];p[0]=(1<<26)-1;for s in 1usize..256{p[s]=p[s&(s-1)]&!g[26+s.trailing_zeros()as usize]}for s in 0usize..256{let t=8-s.count_ones();if has(g,p[s],(t+1).min(8)){a[(t as usize).saturating_sub(4)]+=1}}a}fn energy(a:[i32;5])->f64{(a[0]*15+a[1]*3+a[2]+a[3]+a[4])as f64}fn toggle(g:&mut G,i:usize,j:usize){g[i]^=1<<j;g[j]^=1<<i}fn apply(g:&mut G,(a,b,c,d):(usize,usize,usize,usize))->bool{if a==d||a==c||b==c||b==d||a>=26&&c>=26||b>=26&&d>=26||g[a]>>c&1!=0||g[b]>>d&1!=0{return false}toggle(g,a,b);toggle(g,c,d);if g[a]&g[c]!=0||g[b]&g[d]!=0{toggle(g,a,b);toggle(g,c,d);return false}toggle(g,a,c);toggle(g,b,d);true}fn edges(g:&G)->Vec<(usize,usize)>{(0..34).flat_map(|i|(0..i).filter(move|&j|g[i]>>j&1!=0).map(move|j|(i,j))).collect()}fn rand(st:&mut u64)->u64{*st^=*st<<13;*st^=*st>>7;*st^=*st<<17;*st}fn writebest(h:[i32;5],g:&G){println!("{};{}",h.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(" "),g.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(" "))}fn main(){let args:Vec<_>=std::env::args().collect();let mut st=args[1].parse::<u64>().unwrap();let n=args[2].parse::<usize>().unwrap();let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let xs:Vec<_>=text.split_whitespace().map(|s|s.parse().unwrap()).collect();let mut start=[0u64;34];start.copy_from_slice(&xs);let mut champ=start;let mut best=profile(&champ);let mut legal=0;let mut immediate=best;let es=edges(&start);for(i,&(a,b))in es.iter().enumerate(){for &(c,d)in &es[..i]{for (x,y) in [(c,d),(d,c)]{let mut g=start;if apply(&mut g,(a,b,x,y)){legal+=1;let s=profile(&g);immediate=immediate.min(s);if s<best{best=s;champ=g;writebest(s,&g)}}}}}let mut accepted=0;for restart in 0..n{let mut g=if restart%3==0{start}else{champ};let mut sc=energy(profile(&g));let mut es=edges(&g);for t in 0..4000{let f=rand(&mut st)as usize%es.len();let h=rand(&mut st)as usize%es.len();let (a,b)=es[f];let (mut c,mut d)=es[h];if rand(&mut st)&1!=0{std::mem::swap(&mut c,&mut d)}let mut next=g;if !apply(&mut next,(a,b,c,d)){continue}let z=profile(&next);let e=energy(z);if z<best{best=z;champ=next;writebest(z,&champ)}let temp=0.5+(1.-t as f64/4000.)*(2.+(restart%8)as f64);if e<=sc||((rand(&mut st)>>11)as f64)/((1u64<<53)as f64)<((sc-e)/temp).exp(){es[f]=(a,c);es[h]=(b,d);g=next;sc=e;accepted+=1}}}eprintln!("legal {} immediate {:?} accepted {} best {:?}",legal,immediate,accepted,best);writebest(best,&champ)}
